# The envoy_client filter's gate: what job envoy-client reads.
GATE = gate("envoy_client", "envoy-client", reads=reads(
    ("packages/envoy-client/**", f"{at('envoy-client', 'Typecheck Envoy client')}, test and build in packages/envoy-client"),
    (f"{ENVOY}/scripts/approve/**", at("envoy-client", "Typecheck approve-check's session (bunx tsc --noEmit -p ../envoy/scripts/approve)") + ": packages/envoy/scripts/approve/tsconfig.json compiles session.ts, scan.ts and dispatch-env.ts"),
    ("packages/cipher-client/**", f"{at('envoy-client', 'Typecheck Envoy client')} and its tests compile it; packages/envoy-client/src/broker-credential.ts imports brokerTokenClient from @legion/cipher-client/environment, chooseSignIn from @legion/cipher-client/signins and isFinalRefusal from @legion/cipher-client/token-client"),
    (CONTRACTS_SRC, f"{at('envoy-client', 'Build contracts for Envoy client')}; tsconfig paths @legion/contracts -> ../contracts/src/index.ts"),
    (f"{FIX}/dispatch-targeted-delivery.json", "`packages/envoy-client/src/__tests__/delivery.test.ts#targetedDispatchPayload`, `packages/envoy-client/src/__tests__/dispatch-text.test.ts#every delivery notice and reply hint`"),
    (f"{FIX}/envoy-session-no-interests.json", "`packages/envoy-client/src/__tests__/transport.test.ts#noInterestsFixture`"),
    (f"{FIX}/envelope-without-role.json", "`packages/envoy-client/src/__tests__/transport.test.ts#envelopeWithoutRole`"),
    (f"{FIX}/ask-reply-recipients.json", "`packages/envoy-client/src/__tests__/ask-reply-recipients.test.ts#fixture` reads the copies packages/envoy's TestAnAskReplyIsTheSessionsOwnOnlyForItsAskerAndFollowers writes, and the test renders each"),
    (f"{FIX}/dispatch-public-url.json", "`packages/envoy-client/src/__tests__/dispatch-config.test.ts#publicUrlFixture`"),
    ("packages/contracts/schemas/dispatch-openapi.json", "`packages/envoy-client/test/route-answers.ts#document` reads the OpenAPI document the server generates: `packages/envoy-client/src/__tests__/dispatch-write-rows.test.ts#CASES` drives every keyed write of the client against each 2xx answer it declares, and the other tests' stubs of a keyed write serve its route's answer through routeAnswer"),
    (f"{FIX}/session-grant.json", "`packages/envoy-client/test/nats-server.ts#sessionGrantFixture` imports it for sessionGrantConfig, which src/__tests__/session-reply-grant.test.ts runs"),
    (f"{FIX}/dispatch-frame-property.json", "`packages/envoy-client/src/__tests__/dispatch-frame-property.test.ts#fixture` reads it: renders the generated frames packages/envoy's TestEdgeFrameVerdictOnGeneratedDispatchFrames records"),
    (f"{FIX}/dispatch-frame-verdicts.json", "`packages/envoy-client/src/__tests__/dispatch-payload-reader.test.ts#verdicts` reads it: renders every payload of readDispatchPayload's verdicts, which packages/envoy's TestDispatchPayloadIsEventAgreesWithTheHostsReading reads too"),
    (f"{ENVOY}/internal/dispatch/api/testdata/**", "`packages/envoy-client/src/__tests__/askgate-new-asks.test.ts#table` and `packages/envoy-client/src/__tests__/askgate-new-asks.test.ts#an insert opens the ask blocks the Dispatch server adds for it` reads the Dispatch server's table of decision-block inserts, which packages/envoy/internal/dispatch/api's TestDocumentEditAdviceCountsTheAskBlocksTheEditAdded reads too"),
    (f"{ENVOY}/internal/dispatch/api/testdata/status-change/*.json", "`packages/envoy-client/src/__tests__/dispatch-status-rule.test.ts#fixture` reads each of them under `packages/envoy-client/src/__tests__/dispatch-status-rule.test.ts#FIXTURES`: the answers of POST /api/v1/issues/{key}/status-change that packages/envoy/internal/dispatch/api's TestStatusChangeAnswersMatchTheirFixtures writes, which the test's fake Dispatch answers with"),
    ("skills/**", "`packages/envoy-client/src/__tests__/dispatch-advice.test.ts#every skill section a notice cites is a heading of that skill` reads skills/<skill>/SKILL.md for every skill a notice cites"),
    (TEST_FIXTURES_SRC, "packages/envoy-client/src/__tests__ import @legion/test-fixtures"),
    ("docs/site/src/content/docs/dispatch/for-agents.md", "`packages/envoy-client/src/__tests__/plans-command.test.ts#the guide for agents' Plans row states the contract's scale` and `packages/envoy-client/src/__tests__/plans-command.test.ts#REPO_ROOT` reads it: the guide for agents' Plans row, held to the contract's rating scale"),
    (f"{ENVOY}/internal/bus/testdata/private-stream-subjects.json", "`packages/envoy-client/src/__tests__/stream-topics.test.ts#a topic reaching a private stream subject is the listener's rule, case for case` and `packages/envoy-client/src/__tests__/stream-topics.test.ts#SHARED_CASES` reads the listener's own cases by relative path, which packages/envoy/internal/bus's TestReachesPrivateStreamSubjectBoundsInterests reads too"),
) + dispatch_api_types(at("envoy-client", "Typecheck Envoy client")) + bun_job("envoy-client"))
